  + date
}

Customer "1" -- "*" Broker : is assigned to
Customer "1" -- "*" Contract : signs
Customer "1" -- "*" Claim : files
Customer "1" -- "*" Invoice : receives
Broker "1" -- "*" Customer : follows
HeadOffice "1" -- "*" Broker : manages
HeadOffice "1" -- "*" ClaimCase : manages
Offer "0..1" -- "1" Customer : made to
Offer "1" -- "1" Contract : becomes
Contract "1" -- "1" InsuranceProduct : based on
Contract "1" -- "*" Invoice : generates
Claim "1" -- "1..*" ClaimCase : results in
ClaimCase "1" -- "*" EstimatorReport : assessed by
ClaimCase "1" -- "0..1" CompensationDecision : results in
Estimator "1" -- "*" EstimatorReport : issues
EstimatorReport "1" -- "1" ClaimCase : belongs to

@enduml

